// classes-remote.ts: instructor classes from Supabase. RLS limits rows to classes this instructor
// owns; the join code is generated by the database.
import { appError, fail, type Result } from "@/core/data/errors/app-error";
import { db, guard, must, mustOk, myId, parseSectionLabel, sectionLabel, SECTION_HINT } from "@/core/data/supabase/remote";
import { newId } from "@/shared/utils/id";
import type { InstructorClassRepository } from "@/features/instructor/data/classes-repository";
import type { InstructorClass } from "@/features/instructor/types/instructor";

const COLS = "id, subject_code, title, course, year_level, section, join_code, archived";

type Row = {
  id: string;
  subject_code: string;
  title: string;
  course: string;
  year_level: string;
  section: string;
  join_code: string;
  archived: boolean;
};

async function counts(ids: string[]): Promise<Map<string, number>> {
  const map = new Map<string, number>();
  if (ids.length === 0) return map;
  const rows = must(await db().from("class_enrollments").select("class_id").in("class_id", ids).is("left_at", null));
  for (const r of rows) map.set(r.class_id, (map.get(r.class_id) ?? 0) + 1);
  return map;
}

const toClass = (r: Row, n: number): InstructorClass => ({
  id: r.id,
  code: r.subject_code,
  title: r.title,
  section: sectionLabel(r.course, r.year_level, r.section),
  studentCount: n,
  joinCode: r.join_code,
  archived: r.archived,
});

export class RemoteInstructorClassRepository implements InstructorClassRepository {
  list(): Promise<Result<InstructorClass[]>> {
    return guard(async () => {
      const me = await myId();
      const rows = must(await db().from("classes").select(COLS).eq("instructor_id", me).eq("archived", false).order("created_at", { ascending: false })) as Row[];
      const n = await counts(rows.map((r) => r.id));
      return rows.map((r) => toClass(r, n.get(r.id) ?? 0));
    });
  }

  get(id: string): Promise<Result<InstructorClass | null>> {
    return guard(async () => {
      const me = await myId();
      const row = must(await db().from("classes").select(COLS).eq("id", id).eq("instructor_id", me).maybeSingle()) as Row | null;
      if (!row) return null;
      const n = await counts([id]);
      return toClass(row, n.get(id) ?? 0);
    });
  }

  async create(input: { title: string; section: string; code: string }): Promise<Result<InstructorClass>> {
    const parsed = parseSectionLabel(input.section);
    if (!parsed) return fail(appError("validation", SECTION_HINT, false));
    return guard(async () => {
      const me = await myId();
      // Client-side id + no RETURNING: the select policy calls a function that reads `classes`, which
      // can not see the row this same statement is inserting (it would fail with 42501).
      const id = newId("cls");
      mustOk(
        await db()
          .from("classes")
          .insert({ id, subject_code: input.code.trim(), title: input.title.trim(), course: parsed.course, year_level: parsed.year, section: parsed.section, instructor_id: me }),
      );
      const row = must(await db().from("classes").select(COLS).eq("id", id).single()) as Row;
      return toClass(row, 0);
    });
  }

  archive(id: string, archived: boolean): Promise<Result<void>> {
    return guard(async () => {
      mustOk(await db().from("classes").update({ archived }).eq("id", id));
    }, "This class no longer exists.");
  }

  remove(id: string): Promise<Result<void>> {
    return guard(async () => {
      mustOk(await db().rpc("delete_class", { p_class_id: id }));
    }, "This class no longer exists.");
  }
}
